// Les paramètres s'écrivent {nom} dans les textes.
export const translate = (lang, key, params) => {
  const text = DICT[lang]?.[key] ?? DICT[DEFAULT_LANG][key] ?? key;
  return params ? text.replace(/\{(\w+)\}/g, (m, name) => (name in params ? String(params[name]) : m)) : text;
};

